operation.add:
        
        // WhatsApp, Telegram
        $phone = $order_info['telephone'];

        // Оставляем только цифры
        $digits = preg_replace('/\D+/', '', $phone);

        // WhatsApp: wa.me принимает только цифры, без '+'
        $data['messenger_wa'] = $digits;

        // Telegram: t.me/+<номер> — нужен ведущий '+'
        $data['messenger_tg'] = '+' . $digits;
